class Base {
public:
    // The 'virtual' keyword enables runtime polymorphism
    virtual void process_data() const;

    // Necessary for correct polymorphic destruction
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    // Overrides the base behavior
    void process_data() const override;

    // Derived class uses base virtual destructor
    ~Derived() override = default;
};

// Pure virtual function (Abstract Base Class)
class Interface {
public:
    virtual void execute() = 0; // "= 0" makes it pure
    virtual ~Interface() = default;
};
